INSERT INTO `expert_knowledge` (`id`, `kategori_id`, `sub_kategori`, `jenis_pengetahuan`, `judul`, `konten`, `contoh_soal`, `contoh_penyelesaian`, `kunci_kata`, `tingkat_kesulitan`, `prioritas`, `is_active`, `created_by`, `created_at`, `updated_at`) VALUES
(26, 1, 'TWK', 'logika', 'UUD 1945: Pasal Hak Warga Negara', 'Untuk soal tentang UUD 1945, fokus pada Pasal 27-34 yang berkaitan dengan hak dan kewajiban warga negara. Pasal 27: hak dan kewajiban warga negara. Pasal 28: hak asasi manusia. Pasal 29: kewajiban agama. Pasal 30: pertahanan negara. Pasal 31: pendidikan dan pengajaran. Pasal 32: perekonomian nasional. Pasal 33: ekonomi, penguasaan cabang produksi penting. Pasal 34: fakir miskin dan anak terlantar.', NULL, NULL, 'uud 1945 pasal hak warga negara 27 28 29 30 31 32 33 34', '', 5, 1, NULL, '2026-05-14 01:53:25', '2026-05-14 01:53:25'),
(27, 1, 'TWK', 'logika', 'Pancasila: Pengamalan Sila dalam Kehidupan', 'Sila 1 (Ketuhanan): hubungan dengan Tuhan, kebebasan beragama. Sila 2 (Kemanusiaan): HAM, menghargai martabat manusia. Sila 3 (Persatuan): nasionalisme, toleransi, Bhinneka Tunggal Ika. Sila 4 (Kerakyatan): demokrasi, musyawarah, gotong royong. Sila 5 (Keadilan Sosial): kesejahteraan sosial, keadilan ekonomi.', NULL, NULL, 'pancasila sila ketuhanan kemanusiaan persatuan kerakyatan keadilan', '', 5, 1, NULL, '2026-05-14 01:53:25', '2026-05-14 01:53:25'),
(28, 1, 'TWK', 'logika', 'Bhinneka Tunggal Ika: Persatuan dalam Keberagaman', 'Bhinneka Tunggal Ika berarti \"Berbeda-beda tetapi tetap satu juga\". Nilai yang dijunjung: toleransi, saling menghargai perbedaan, tidak memaksakan kehendak, menjaga harmoni sosial, mengutamakan persatuan di atas perbedaan.', NULL, NULL, 'bhinneka tunggal ika persatuan keberagaman toleransi', '', 5, 1, NULL, '2026-05-14 01:53:25', '2026-05-14 01:53:25'),
(29, 1, 'TIU', 'metode_cepat', 'Perhitungan Matematika: Operasi Dasar', 'Untuk soal perhitungan matematika dasar: 1) Kuadrat sempurna 1-100: 1,4,9,16,25,36,49,64,81,100. 2) Pangkat 2: 2²=4, 3²=9, 4²=16, 5²=25, 6²=36, 7²=49, 8²=64, 9²=81, 10²=100, 11²=121, 12²=144. 3) Pangkat 3: 2³=8, 3³=27, 4³=64, 5³=125. 4) Operasi dasar: prioritaskan perkalian/pembagian sebelum penjumlahan/pengurangan.', NULL, NULL, 'hitung nilai matematika dasar kuadrat pangkat', '', 5, 1, NULL, '2026-05-14 01:53:25', '2026-05-14 01:53:25'),
(30, 1, 'TIU', 'metode_cepat', 'Trigonometri: Nilai Sudut Istimewa', 'Ingat nilai trigonometri sudut istimewa: sin 0°=0, sin 30°=1/2, sin 45°=√2/2, sin 60°=√3/2, sin 90°=1. cos 0°=1, cos 30°=√3/2, cos 45°=√2/2, cos 60°=1/2, cos 90°=0. tan 0°=0, tan 30°=1/√3, tan 45°=1, tan 60°=√3. Ingat juga: sin²+cos²=1, tan=sin/cos.', NULL, NULL, 'sin cos tan trigonometri sudut istimewa', '', 5, 1, NULL, '2026-05-14 01:53:25', '2026-05-14 01:53:25'),
(31, 1, 'TIU', 'metode_cepat', 'Analogi: Hubungan Kata', 'Untuk analogi: 1) Identifikasi hubungan antara dua kata pertama. 2) Cari hubungan yang sama untuk kata ketiga dan pilihan jawaban. 3) Jenis hubungan: sinonim (kata yang sama artinya), antonim (berlawanan), bagian-keseluruhan (buku-halaman), sebab-akibat (hujan-basah), jenis-kategori (mangga-buah), fungsi (kunci-pintu).', NULL, NULL, 'analogi hubungan kata sinonim antonim', '', 5, 1, NULL, '2026-05-14 01:53:25', '2026-05-14 01:53:25'),
(32, 1, 'TIU', 'metode_cepat', 'Deret dan Pola Angka', 'Untuk deret: 1) Cari selisih antar suku (deret aritmatika). 2) Cari rasio (deret geometri). 3) Cari pola khusus (kuadrat, pangkat, campuran). 4) Rumus aritmatika: Un = a + (n-1)b. 5) Rumus geometri: Un = a × r^(n-1). 6) Untuk pola campuran, identifikasi dua atau lebih pola yang digabung.', NULL, NULL, 'deret pola angka aritmatika geometri', '', 5, 1, NULL, '2026-05-14 01:53:25', '2026-05-14 01:53:25'),
(33, 1, 'TKP', 'logika', 'Sikap Profesional di Lingkungan Kerja', 'Dalam situasi kerja, pilih jawaban yang menunjukkan: 1) Kepentingan instansi di atas kepentingan pribadi. 2) Sikap profesional dan bertanggung jawab. 3) Kerja sama dan kolaborasi. 4) Integritas dan kejujuran. 5) Empati terhadap rekan kerja. Hindari jawaban yang egois, tidak profesional, atau merugikan instansi.', NULL, NULL, 'tkp sikap situasi kerja profesional', '', 5, 1, NULL, '2026-05-14 01:53:25', '2026-05-14 01:53:25'),
(34, 1, 'TKP', 'logika', 'Pelayanan Publik yang Baik', 'Untuk pelayanan publik: 1) Keramah-tamahan dalam melayani. 2) Responsif terhadap kebutuhan masyarakat. 3) Efektifitas dan efisiensi. 4) Integritas dalam pelayanan. 5) Tidak meminta imbalan tambahan. 6) Mendengarkan keluhan dengan empati. 7) Berusaha mencari solusi yang memuaskan.', NULL, NULL, 'tkp pelayanan publik melayani masyarakat', '', 5, 1, NULL, '2026-05-14 01:53:25', '2026-05-14 01:53:25'),
(35, 1, 'TPA', 'metode_cepat', 'Sinonim: Kata yang Sama Artinya', 'Untuk soal sinonim: 1) Baca dengan teliti kata yang diminta sinonimnya. 2) Perhatikan konteks kalimat untuk memahami nuansa. 3) Pilih kata yang memiliki arti paling dekat atau sama persis. 4) Hindari kata yang memiliki arti mirip tapi tidak sama. 5) Beberapa kata mungkin memiliki makna ganda tergantung konteks.', NULL, NULL, 'tpa sinonim kata arti sama', '', 5, 1, NULL, '2026-05-14 01:53:25', '2026-05-14 01:53:25'),
(36, 1, 'TPA', 'metode_cepat', 'Antonim: Kata yang Berlawanan', 'Untuk soal antonim: 1) Identifikasi kata yang diminta antonimnya. 2) Pilih kata yang memiliki arti berlawanan. 3) Perhatikan prefiks/sufis yang sering menunjukkan lawan (tidak-, non-, anti-). 4) Pastikan antonim sesuai dengan konteks kalimat. 5) Hindari kata yang hanya sedikit berbeda.', NULL, NULL, 'tpa antonim kata lawan berlawanan', '', 5, 1, NULL, '2026-05-14 01:53:26', '2026-05-14 01:53:26'),
(37, 1, 'PSIKOLOGIS', 'logika', 'Motivasi Bekerja di Sekolah Kedinasan', 'Untuk soal motivasi: Motivasi yang baik untuk bekerja di sekolah kedinasan adalah: 1) Mengabdi untuk negara dan bangsa. 2) Membangun karier yang bermanfaat. 3) Mengembangkan potensi diri. 4) Kontribusi positif bagi masyarakat. Hindari motivasi yang bersifat materialistis atau egois.', NULL, NULL, 'psikologis motivasi kerja sekolah kedinasan', '', 5, 1, NULL, '2026-05-14 01:53:26', '2026-05-14 01:53:26'),
(38, 1, 'PSIKOLOGIS', 'logika', 'Manajemen Stres di Tempat Kerja', 'Untuk manajemen stres: Strategi coping yang sehat: 1) Mengelola emosi dengan baik. 2) Mencari dukungan sosial. 3) Menjaga work-life balance. 4) Mengembangkan resiliensi. 5) Melakukan aktivitas yang menyenangkan. 6) Tidak ragu meminta bantuan jika diperlukan.', NULL, NULL, 'psikologis stres manajemen emosi coping', '', 5, 1, NULL, '2026-05-14 01:53:26', '2026-05-14 01:53:26'),
(39, 1, 'TWK', 'logika', 'Sejarah Indonesia: Masa Penjajahan', 'Untuk soal tentang sejarah penjajahan: Ingat timeline penjajahan: Portugis (1511), VOC (1602), Inggris (1811-1816), Jepang (1942-1945). Fokus pada: kebijakan penjajah, perlawanan rakyat, organisasi pergerakan nasional (Budi Utomo, Sarekat Islam, PNI, PKI, dll), tokoh pergerakan (Soekarno, Hatta, dll).', NULL, NULL, 'sejarah jepang inggris portugis voc penjajah pergerakan nasional', '', 5, 1, NULL, '2026-05-14 01:58:29', '2026-05-14 01:58:29'),
(40, 1, 'TWK', 'logika', 'Wawasan Kebangsaan dan Nusantara', 'Wawasan Nusantara: konsep geopolitik Indonesia sebagai negara kepulauan. Fokus pada: posisi strategis, kedaulatan wilayah, batas laut dan darat, sumber daya alam, keanekaragaman budaya. Wawasan kebangsaan: pemahaman tentang identitas bangsa, sejarah, budaya, dan masa depan Indonesia.', NULL, NULL, 'wawasan kebangsaan nusantara geopolitik wilayah batas', '', 5, 1, NULL, '2026-05-14 01:58:29', '2026-05-14 01:58:29'),
(41, 1, 'TIU', 'metode_cepat', 'Perhitungan: Akar dan Persen', 'Untuk soal akar: √1=1, √4=2, √9=3, √16=4, √25=5, √36=6, √49=7, √64=8, √81=9, √100=10, √121=11, √144=12, √169=13. Untuk persen: 10% = 0.1, 20% = 0.2, 25% = 0.25, 50% = 0.5, 75% = 0.75. Rumus: x% dari y = (x/100) × y.', NULL, NULL, 'hitung akar persen perhitungan matematika', '', 5, 1, NULL, '2026-05-14 01:58:29', '2026-05-14 01:58:29'),
(42, 1, 'TIU', 'metode_cepat', 'Peribahasa dan Idiom', 'Untuk soal peribahasa/idiom: 1) Baca peribahasa dengan teliti. 2) Pahami makna literal dan makna kiasan. 3) Pilih jawaban yang sesuai dengan konteks. Contoh: \"Seperti rusa masuk kampung\" = orang yang tidak dikenal datang ke tempat asing. \"Bagai kuku dengan daging\" = tidak bisa dipisahkan.', NULL, NULL, 'peribahasa idiom makna kiasan', '', 5, 1, NULL, '2026-05-14 01:58:29', '2026-05-14 01:58:29'),
(43, 1, 'TIU', 'metode_cepat', 'Silogisme dan Logika Deduktif', 'Untuk silogisme: 1) Identifikasi premis mayor (umum) dan premis minor (khusus). 2) Gunakan aturan logika: jika semua A adalah B, dan C adalah A, maka C adalah B. 3) Hati-hati dengan negasi: \"tidak semua\" berarti \"beberapa bukan\". 4) Kesimpulan harus mengikuti secara logis dari premis.', NULL, NULL, 'silogisme logika premis kesimpulan deduktif', '', 5, 1, NULL, '2026-05-14 01:58:29', '2026-05-14 01:58:29'),
(44, 1, 'TKP', 'logika', 'Integritas dan Anti-Korupsi', 'Untuk soal tentang integritas: Pilih jawaban yang menunjukkan: 1) Menolak suap/korupsi. 2) Menjunjung kejujuran. 3) Mengutamakan kepentingan publik. 4) Tidak menggunakan jabatan untuk keuntungan pribadi. 5) Melaporkan pelanggaran. Hindari jawaban yang menerima suap atau kompromi.', NULL, NULL, 'tkp integritas korupsi suap jujur', '', 5, 1, NULL, '2026-05-14 01:58:29', '2026-05-14 01:58:29'),
(45, 1, 'TKP', 'logika', 'Penyelesaian Konflik dan Kerja Tim', 'Untuk penyelesaian konflik: 1) Dengarkan semua pihak dengan empati. 2) Cari solusi win-win. 3) Jangan mengambil pihak. 4) Fokus pada masalah, bukan pribadi. 5) Mediasi jika diperlukan. 6) Jaga profesionalitas. Untuk kerja tim: 1) Kolaborasi dan komunikasi. 2) Menghargai kontribusi orang lain. 3) Membagi tanggung jawab.', NULL, NULL, 'tkp konflik kerja tim kolaborasi komunikasi', '', 5, 1, NULL, '2026-05-14 01:58:29', '2026-05-14 01:58:29'),
(46, 1, 'TPA', 'metode_cepat', 'Analogi: Hubungan Kata dan Konsep', 'Untuk analogi TPA: 1) Identifikasi hubungan antar kata pertama. 2) Cari hubungan yang sama di pilihan jawaban. 3) Jenis hubungan: profesi-alat (dokter-stetoskop), bagian-keseluruhan (halaman-buku), sebab-akibat (hujan-basah), fungsi (kunci-pintu), karakteristik (singa-garang). 4) Pilih yang paling tepat.', NULL, NULL, 'tpa analogi hubungan profesi fungsi karakteristik', '', 5, 1, NULL, '2026-05-14 01:58:29', '2026-05-14 01:58:29'),
(47, 1, 'PSIKOLOGIS', 'logika', 'Gaya Kerja dan Preferensi', 'Untuk soal gaya kerja: Jawab dengan jujur sesuai preferensi Anda. Tidak ada jawaban benar atau salah - ini untuk memahami kepribadian. Pilih yang paling menggambarkan diri Anda: suka bekerja sendiri atau tim, detail-oriented atau big picture, terstruktur atau fleksibel.', NULL, NULL, 'psikologis gaya kerja preferensi kepribadian', '', 5, 1, NULL, '2026-05-14 01:58:29', '2026-05-14 01:58:29'),
(48, 1, 'PSIKOLOGIS', 'logika', 'Pengendalian Diri dan Disiplin', 'Untuk soal pengendalian diri: Menunjukkan kemampuan: 1) Mengelola emosi. 2) Menahan diri dari impuls negatif. 3. Disiplin dalam bekerja. 4) Konsistensi dalam perilaku. 5) Mampu fokus pada tujuan. Pilih jawaban yang menunjukkan kontrol diri yang baik.', NULL, NULL, 'psikologis pengendalian diri disiplin emosi', '', 5, 1, NULL, '2026-05-14 01:58:29', '2026-05-14 01:58:29'),
(49, 1, 'TWK', 'logika', 'Sejarah Indonesia: Masa Penjajahan', 'Untuk soal tentang sejarah penjajahan: Ingat timeline penjajahan: Portugis (1511), VOC (1602), Inggris (1811-1816), Jepang (1942-1945). Fokus pada: kebijakan penjajah, perlawanan rakyat, organisasi pergerakan nasional (Budi Utomo, Sarekat Islam, PNI, PKI, dll), tokoh pergerakan (Soekarno, Hatta, dll).', NULL, NULL, 'sejarah jepang inggris portugis voc penjajah pergerakan nasional', '', 5, 1, NULL, '2026-05-14 01:59:58', '2026-05-14 01:59:58'),
(50, 1, 'TWK', 'logika', 'Wawasan Kebangsaan dan Nusantara', 'Wawasan Nusantara: konsep geopolitik Indonesia sebagai negara kepulauan. Fokus pada: posisi strategis, kedaulatan wilayah, batas laut dan darat, sumber daya alam, keanekaragaman budaya. Wawasan kebangsaan: pemahaman tentang identitas bangsa, sejarah, budaya, dan masa depan Indonesia.', NULL, NULL, 'wawasan kebangsaan nusantara geopolitik wilayah batas', '', 5, 1, NULL, '2026-05-14 01:59:58', '2026-05-14 01:59:58'),
(51, 1, 'TIU', 'metode_cepat', 'Perhitungan: Akar dan Persen', 'Untuk soal akar: √1=1, √4=2, √9=3, √16=4, √25=5, √36=6, √49=7, √64=8, √81=9, √100=10, √121=11, √144=12, √169=13. Untuk persen: 10% = 0.1, 20% = 0.2, 25% = 0.25, 50% = 0.5, 75% = 0.75. Rumus: x% dari y = (x/100) × y.', NULL, NULL, 'hitung akar persen perhitungan matematika', '', 5, 1, NULL, '2026-05-14 01:59:58', '2026-05-14 01:59:58'),
(52, 1, 'TIU', 'metode_cepat', 'Peribahasa dan Idiom', 'Untuk soal peribahasa/idiom: 1) Baca peribahasa dengan teliti. 2) Pahami makna literal dan makna kiasan. 3) Pilih jawaban yang sesuai dengan konteks. Contoh: \"Seperti rusa masuk kampung\" = orang yang tidak dikenal datang ke tempat asing. \"Bagai kuku dengan daging\" = tidak bisa dipisahkan.', NULL, NULL, 'peribahasa idiom makna kiasan', '', 5, 1, NULL, '2026-05-14 01:59:58', '2026-05-14 01:59:58'),
(53, 1, 'TIU', 'metode_cepat', 'Silogisme dan Logika Deduktif', 'Untuk silogisme: 1) Identifikasi premis mayor (umum) dan premis minor (khusus). 2) Gunakan aturan logika: jika semua A adalah B, dan C adalah A, maka C adalah B. 3) Hati-hati dengan negasi: \"tidak semua\" berarti \"beberapa bukan\". 4) Kesimpulan harus mengikuti secara logis dari premis.', NULL, NULL, 'silogisme logika premis kesimpulan deduktif', '', 5, 1, NULL, '2026-05-14 01:59:58', '2026-05-14 01:59:58'),
(54, 1, 'TKP', 'logika', 'Integritas dan Anti-Korupsi', 'Untuk soal tentang integritas: Pilih jawaban yang menunjukkan: 1) Menolak suap/korupsi. 2) Menjunjung kejujuran. 3) Mengutamakan kepentingan publik. 4) Tidak menggunakan jabatan untuk keuntungan pribadi. 5) Melaporkan pelanggaran. Hindari jawaban yang menerima suap atau kompromi.', NULL, NULL, 'tkp integritas korupsi suap jujur', '', 5, 1, NULL, '2026-05-14 01:59:58', '2026-05-14 01:59:58'),
(55, 1, 'TKP', 'logika', 'Penyelesaian Konflik dan Kerja Tim', 'Untuk penyelesaian konflik: 1) Dengarkan semua pihak dengan empati. 2) Cari solusi win-win. 3) Jangan mengambil pihak. 4) Fokus pada masalah, bukan pribadi. 5) Mediasi jika diperlukan. 6) Jaga profesionalitas. Untuk kerja tim: 1) Kolaborasi dan komunikasi. 2) Menghargai kontribusi orang lain. 3) Membagi tanggung jawab.', NULL, NULL, 'tkp konflik kerja tim kolaborasi komunikasi', '', 5, 1, NULL, '2026-05-14 01:59:58', '2026-05-14 01:59:58'),
(56, 1, 'TPA', 'metode_cepat', 'Analogi: Hubungan Kata dan Konsep', 'Untuk analogi TPA: 1) Identifikasi hubungan antar kata pertama. 2) Cari hubungan yang sama di pilihan jawaban. 3) Jenis hubungan: profesi-alat (dokter-stetoskop), bagian-keseluruhan (halaman-buku), sebab-akibat (hujan-basah), fungsi (kunci-pintu), karakteristik (singa-garang). 4) Pilih yang paling tepat.', NULL, NULL, 'tpa analogi hubungan profesi fungsi karakteristik', '', 5, 1, NULL, '2026-05-14 01:59:58', '2026-05-14 01:59:58'),
(57, 1, 'PSIKOLOGIS', 'logika', 'Gaya Kerja dan Preferensi', 'Untuk soal gaya kerja: Jawab dengan jujur sesuai preferensi Anda. Tidak ada jawaban benar atau salah - ini untuk memahami kepribadian. Pilih yang paling menggambarkan diri Anda: suka bekerja sendiri atau tim, detail-oriented atau big picture, terstruktur atau fleksibel.', NULL, NULL, 'psikologis gaya kerja preferensi kepribadian', '', 5, 1, NULL, '2026-05-14 01:59:58', '2026-05-14 01:59:58'),
(58, 1, 'PSIKOLOGIS', 'logika', 'Pengendalian Diri dan Disiplin', 'Untuk soal pengendalian diri: Menunjukkan kemampuan: 1) Mengelola emosi. 2) Menahan diri dari impuls negatif. 3. Disiplin dalam bekerja. 4) Konsistensi dalam perilaku. 5) Mampu fokus pada tujuan. Pilih jawaban yang menunjukkan kontrol diri yang baik.', NULL, NULL, 'psikologis pengendalian diri disiplin emosi', '', 5, 1, NULL, '2026-05-14 01:59:58', '2026-05-14 01:59:58'),
(59, 1, 'TWK', 'logika', 'Sejarah Indonesia: Masa Penjajahan', 'Untuk soal tentang sejarah penjajahan: Ingat timeline penjajahan: Portugis (1511), VOC (1602), Inggris (1811-1816), Jepang (1942-1945). Fokus pada: kebijakan penjajah, perlawanan rakyat, organisasi pergerakan nasional (Budi Utomo, Sarekat Islam, PNI, PKI, dll), tokoh pergerakan (Soekarno, Hatta, dll).', NULL, NULL, 'sejarah jepang inggris portugis voc penjajah pergerakan nasional', '', 5, 1, NULL, '2026-05-14 02:02:00', '2026-05-14 02:02:00'),
