INSERT INTO `sesi_ujian` (`id`, `nama_peserta`, `user_id`, `waktu_mulai`, `waktu_selesai`, `durasi_menit`, `soal_teracak`, `jawaban_sementara`, `status`, `ability_estimate`, `ability_history`, `confidence_level`, `cat_enabled`) VALUES
(1, 'Lidia', NULL, '2026-05-09 18:33:08', NULL, 100, '[{\"id\":\"3\",\"pertanyaan\":\"Pada 2021 silam, seorang aparat bernama Briptu Nikmal Idwan diduga melakukan pemerkosaan terhadap seorang remaja perempuan berusia 16 tahun di Mapolsek Jailolo Selatan, Halmahera Barat, Maluku Utara. Tindakan aparat ini jelas sekali bertentangan dengan....\",\"opsi_a\":\"UUD 1945 pasal 27 ayat 3\",\"opsi_b\":\"UUD 1945 pasal 30 ayat 3\",\"opsi_c\":\"UUD 1945 pasal 30 ayat 4\",\"opsi_d\":\"UU nomor 3 2002 pasal 9 ayat 1\",\"opsi_e\":\"UU nomor 3 2002 pasal 9 ayat 2\",\"jawaban_benar\":\"C\",\"kategori_id\":\"1\",\"nomor\":1,\"kategori\":\"TWK\"},{\"id\":\"1\",\"pertanyaan\":\"Negara X adalah sebuah negara yang baru saja merdeka dan sedang berusaha membangun rasa nasionalisme di kalangan warganya. Proses ini dilakukan melalui implementasi berbagai program pemerintah dan penyebaran nilai-nilai patriotisme dalam pendidikan. Namun, beberapa tantangan tampaknya menjadi penghambat dalam upaya tersebut. Antara lain: Banyak warga Negara X yang memilih untuk bekerja di negara lain dan mengadopsi gaya hidup serta budaya negara tersebut. Sebagian masyarakat Negara X lebih tertarik pada barang-barang impor dibandingkan produk lokal. Penyiaran dan media di Negara X banyak didominasi oleh konten dari luar negeri. Konflik internal antara berbagai kelompok etnis dan agama yang berbeda. Pengetahuan dan apresiasi terhadap sejarah dan budaya lokal cukup tinggi di kalangan masyarakat berusia. Berdasarkan kasus di atas, mana faktor yang paling mungkin menjadi penghambat utama dalam membangun semangat nasionalisme di Negara X?\",\"opsi_a\":\"Globalisasi\",\"opsi_b\":\"Kesenjangan sosial\",\"opsi_c\":\"Pendidikan yang kurang efektif\",\"opsi_d\":\"Sumber daya manusia yang kurang\",\"opsi_e\":\"Kurangnya dukungan dari pemerintah\",\"jawaban_benar\":\"A\",\"kategori_id\":\"1\",\"nomor\":2,\"kategori\":\"TWK\"},{\"id\":\"4\",\"pertanyaan\":\"Nama Pandawara Group seringkali menjadi perbincangan dan trending topik di sosial media berkat aksi-aksi heroiknya dalam membersihkan sampah. Beranggotakan lima orang pemuda, yaitu Ikhsan Destian, Gliang Rahma, Muhammad Rifqi, Rafly Pasya, dan Agung Permana, tak jarang Pandawara Group mengajak masyarakat dan netizen untuk turut serta turun ke lapangan membersihkan sampah. Aksi kelompok pemuda ini mencerminkan salah satu nilai bela negara, yaitu....\",\"opsi_a\":\"cinta tanah air\",\"opsi_b\":\"kesadaran berbangsa dan bernegara\",\"opsi_c\":\"rela berkorban\",\"opsi_d\":\"memiliki kemampuan bela negara\",\"opsi_e\":\"memiliki kemampuan awal bela negara\",\"jawaban_benar\":\"A\",\"kategori_id\":\"1\",\"nomor\":3,\"kategori\":\"TWK\"},{\"id\":\"2\",\"pertanyaan\":\"Pada masa penjajahan, beberapa pemuda Indonesia seperti Ernest Douwes Dekker, Soewardi Soerjaningrat dan Tjipto Mangunkusumo mendirikan organisasi yang bernama Indische Party. Organisasi ini dikenal sebagai organisasi pertama yang mencetuskan konsep merdeka, yaitu bebas dari penjajahan Belanda dan menjadi fondasi penting dalam paham nasionalisme Indonesia. Peran Indische Party dan konsep merdeka memiliki pengaruh yang signifikan dalam sejarah kemerdekaan Indonesia. Bagaimanakah dampak konsep merdeka dan paham nasionalisme yang ditetapkan oleh Indische Party dalam perjuangan bangsa Indonesia hingga hari ini?\",\"opsi_a\":\"Menginspirasi pembuatan Pancasila sebagai dasar negara\",\"opsi_b\":\"Mendorong pertumbuhan partai-partai politik di Indonesia\",\"opsi_c\":\"Mendorong terbentuknya kesadaran kolektif untuk merdeka\",\"opsi_d\":\"Mendorong penggunaan Bahasa Indonesia sebagai bahasa resmi\",\"opsi_e\":\"Menstimulasi pembentukan lembaga-lembaga pemerintahan setelah kemerdekaan\",\"jawaban_benar\":\"C\",\"kategori_id\":\"1\",\"nomor\":4,\"kategori\":\"TWK\"},{\"id\":\"5\",\"pertanyaan\":\"Sikap di bawah ini yang berlandaskan nasionalisme yang berpengaruh pada kebijakan fiskal negara ialah....\",\"opsi_a\":\"Melakukan pembayaran pajak tepat pada waktu yang ditentukan\",\"opsi_b\":\"Melakukan suatu pekerjaan yang tidak bertentangan dengan hukum\",\"opsi_c\":\"Membeli produk-produk buatan dalam negeri\",\"opsi_d\":\"Menggunakan hak pilih pada pemilihan umum (pemilu)\",\"opsi_e\":\"Memiliki sikap toleransi tinggi terhadap orang\\/masyarakat yang berbeda keyakinan\",\"jawaban_benar\":\"A\",\"kategori_id\":\"1\",\"nomor\":5,\"kategori\":\"TWK\"},{\"id\":\"9\",\"pertanyaan\":\"Perhatikan pernyataan berikut! Setiap manusia di dunia pernah mengalami gigi rontok. Beberapa manusia di dunia adalah orang yang sangat tampan. Jadi,....\",\"opsi_a\":\"Beberapa manusia yang sangat tampan tidak pernah mengalami rontok gigi.\",\"opsi_b\":\"Beberapa manusia yang sangat tampan pernah mengalami rontok gigi.\",\"opsi_c\":\"Semua manusia yang sangat tampan tidak pernah mengalami rontok gigi.\",\"opsi_d\":\"Semua manusia yang sangat tampan pernah mengalami rontok gigi.\",\"opsi_e\":\"Semua manusia yang pernah mengalami rontok gigi adalah manusia yang sangat tampan.\",\"jawaban_benar\":\"B\",\"kategori_id\":\"2\",\"nomor\":6,\"kategori\":\"TIU\"},{\"id\":\"11\",\"pertanyaan\":\"65, 60, 45, 40, ..., 20, 10, 5\",\"opsi_a\":\"5\",\"opsi_b\":\"25\",\"opsi_c\":\"30\",\"opsi_d\":\"35\",\"opsi_e\":\"40\",\"jawaban_benar\":\"B\",\"kategori_id\":\"2\",\"nomor\":7,\"kategori\":\"TIU\"},{\"id\":\"8\",\"pertanyaan\":\"Hubungan yang terdapat pada kalimat ikan adalah ekor sama seperti hubungan pada kalimat....\",\"opsi_a\":\"Manusia adalah kaki.\",\"opsi_b\":\"Kucing adalah buntut.\",\"opsi_c\":\"Daun adalah helai.\",\"opsi_d\":\"Bunga adalah buah.\",\"opsi_e\":\"Rumah adalah hunian.\",\"jawaban_benar\":\"C\",\"kategori_id\":\"2\",\"nomor\":8,\"kategori\":\"TIU\"},{\"id\":\"6\",\"pertanyaan\":\"API : ... = ... : TERBASAHI\",\"opsi_a\":\"PANAS \\u2013 CAIRAN\",\"opsi_b\":\"TERBAKAR \\u2013 AIR\",\"opsi_c\":\"BERBAHAYA \\u2013 GENANGAN\",\"opsi_d\":\"DIHINDARI \\u2013 DIDEKATI\",\"opsi_e\":\"GAS \\u2013 CAIR\",\"jawaban_benar\":\"B\",\"kategori_id\":\"2\",\"nomor\":9,\"kategori\":\"TIU\"},{\"id\":\"12\",\"pertanyaan\":\"Suap : Politik = .......... : ..........\",\"opsi_a\":\"Korupsi : nepotisme\",\"opsi_b\":\"Sontek : Ujian\",\"opsi_c\":\"Perampok : Polisi\",\"opsi_d\":\"Culas : Sifat\",\"opsi_e\":\"Joki : Ganti\",\"jawaban_benar\":\"B\",\"kategori_id\":\"2\",\"nomor\":10,\"kategori\":\"TIU\"},{\"id\":\"13\",\"pertanyaan\":\"Asia : Jepang : Sapporo = ..... : ...... : .........\",\"opsi_a\":\"Asia : Baghdah : Khalifah\",\"opsi_b\":\"Eropa : London : Coloseum\",\"opsi_c\":\"Amerika : Amerika Serikat : Liberty\",\"opsi_d\":\"Kelimutu : Flores : Indonesia\",\"opsi_e\":\"Benua : Pulau : Berpenduduk\",\"jawaban_benar\":\"C\",\"kategori_id\":\"2\",\"nomor\":11,\"kategori\":\"TIU\"},{\"id\":\"7\",\"pertanyaan\":\"KULKAS : SATU PINTU : DUA PINTU = ...\",\"opsi_a\":\"APEL : SATU KERANJANG : DUA KERANJANG\",\"opsi_b\":\"ES KRIM : DINGIN : PANAS\",\"opsi_c\":\"RODA : BULAT : KOTAK\",\"opsi_d\":\"KASUR : RANJANG : ALAS TIDUR\",\"opsi_e\":\"MESIN CUCI : BUKAAN ATAS : BUKAAN DEPAN\",\"jawaban_benar\":\"E\",\"kategori_id\":\"2\",\"nomor\":12,\"kategori\":\"TIU\"},{\"id\":\"10\",\"pertanyaan\":\"Orang-orang yang rajin membaca buku pasti memiliki pengetahuan yang luas. Orang yang memiliki pengetahuan luas sering kali lebih kreatif dalam memecahkan masalah. Hal ini membuat seseorang sukses dalam kariernya. Kesimpulan yang dapat ditarik dari premis-premis di atas adalah....\",\"opsi_a\":\"Orang yang sukses dalam kariernya pasti rajin membaca buku.\",\"opsi_b\":\"Orang yang rajin membaca buku sukses dalam kariernya.\",\"opsi_c\":\"Orang yang kreatif dalam memecahkan masalah pasti memiliki pengetahuan luas.\",\"opsi_d\":\"Orang yang sukses dalam karier pasti sering kali lebih kreatif dalam memecahkan masalah.\",\"opsi_e\":\"Orang yang sukses dalam karier sering kali rajin membaca buku.\",\"jawaban_benar\":\"B\",\"kategori_id\":\"2\",\"nomor\":13,\"kategori\":\"TIU\"},{\"id\":\"18\",\"pertanyaan\":\"Dalam situasi darurat, apa yang akan Anda lakukan?\",\"opsi_a\":\"Panik dan tidak bisa berpikir jernih\",\"opsi_b\":\"Menunggu instruksi dari orang lain tanpa inisiatif\",\"opsi_c\":\"Tetap tenang dan mengambil tindakan yang diperlukan\",\"opsi_d\":\"Lari dari situasi tersebut\",\"opsi_e\":\"Menyalahkan keadaan\",\"jawaban_benar\":\"C\",\"kategori_id\":\"3\",\"nomor\":14,\"kategori\":\"TKP\"},{\"id\":\"17\",\"pertanyaan\":\"Atasan memberikan kritik terhadap pekerjaan Anda. Reaksi Anda adalah....\",\"opsi_a\":\"Marah dan merasa tersinggung\",\"opsi_b\":\"Mengabaikan kritik dan tetap melakukan cara sendiri\",\"opsi_c\":\"Menerima kritik dengan terbuka dan memperbaiki diri\",\"opsi_d\":\"Mencari alasan untuk membela diri\",\"opsi_e\":\"Menggosipkan atasan di belakang\",\"jawaban_benar\":\"C\",\"kategori_id\":\"3\",\"nomor\":15,\"kategori\":\"TKP\"},{\"id\":\"15\",\"pertanyaan\":\"Rekan kerja Anda melakukan kesalahan yang tidak disengaja. Apa tindakan Anda?\",\"opsi_a\":\"Melaporkan ke atasan untuk mendapatkan keuntungan pribadi\",\"opsi_b\":\"Menertawakan dan mengumumkan kesalahan tersebut\",\"opsi_c\":\"Memberi tahu rekan tersebut dan menawarkan bantuan\",\"opsi_d\":\"Pura-pura tidak tahu dan membiarkan saja\",\"opsi_e\":\"Mencari-cari kesalahan lain dari rekan tersebut\",\"jawaban_benar\":\"C\",\"kategori_id\":\"3\",\"nomor\":16,\"kategori\":\"TKP\"},{\"id\":\"16\",\"pertanyaan\":\"Anda mendapatkan tugas baru yang menantang. Sikap Anda adalah....\",\"opsi_a\":\"Menolak tugas tersebut karena terlalu sulit\",\"opsi_b\":\"Menerima tapi tidak serius mengerjakannya\",\"opsi_c\":\"Menerima dengan antusias dan belajar untuk menyelesaikannya\",\"opsi_d\":\"Menunda mengerjakan sampai deadline dekat\",\"opsi_e\":\"Minta orang lain mengerjakan untuk Anda\",\"jawaban_benar\":\"C\",\"kategori_id\":\"3\",\"nomor\":17,\"kategori\":\"TKP\"},{\"id\":\"14\",\"pertanyaan\":\"Saat Anda menghadapi situasi sulit di tempat kerja, apa yang akan Anda lakukan?\",\"opsi_a\":\"Mengeluh dan mencari kesalahan orang lain\",\"opsi_b\":\"Menghindar dan menunda penyelesaian masalah\",\"opsi_c\":\"Menganalisis masalah dan mencari solusi dengan tenang\",\"opsi_d\":\"Meminta bantuan tanpa mencoba menyelesaikan sendiri\",\"opsi_e\":\"Menyerah dan mencari pekerjaan lain\",\"jawaban_benar\":\"C\",\"kategori_id\":\"3\",\"nomor\":18,\"kategori\":\"TKP\"}]', NULL, 'berjalan', 0.0000, NULL, 0.0000, 0),
(2, 'testing', NULL, '2026-05-09 23:53:04', NULL, 100, '[{\"id\":\"10557\",\"pertanyaan\":\"Norma Kesopanan adalah ...\",\"opsi_a\":\"Peraturan yang dianggap sebagai suara hati manusia\",\"opsi_b\":\"Peraturan yang dibuat oleh penguasa negara \\/ lembaga adat\",\"opsi_c\":\"Peraturan yang dibuat oleh agama dan adat\",\"opsi_d\":\"Peraturan yang diciptakan Tuhan bersumber dari kitab suci\",\"opsi_e\":\"Peraturan yang dibuat oleh keluarga secara turun temurun\",\"jawaban_benar\":\"C\",\"kategori_id\":\"1\",\"nomor\":1,\"kategori\":\"TWK\"},{\"id\":\"3295\",\"pertanyaan\":\"Sumber hukum yang berasal dari keyakinan kesadaran individu dan pendapat umum disebut sumber hukum ...\",\"opsi_a\":\"Formal\",\"opsi_b\":\"Material\",\"opsi_c\":\"Yurisprudensi\",\"opsi_d\":\"Traktat\",\"opsi_e\":\"Konvensi\",\"jawaban_benar\":\"E\",\"kategori_id\":\"1\",\"nomor\":2,\"kategori\":\"TWK\"},{\"id\":\"2365\",\"pertanyaan\":\"Ketua Panitia BPUPKI adalah...\",\"opsi_a\":\"Hatta\",\"opsi_b\":\"Sutan Syahrir\",\"opsi_c\":\"Sayuti Melik\",\"opsi_d\":\"Agus Salim\",\"opsi_e\":\"\",\"jawaban_benar\":\"B\",\"kategori_id\":\"1\",\"nomor\":3,\"kategori\":\"TWK\"},{\"id\":\"2386\",\"pertanyaan\":\"Peristiwa nahas ini terjadi saat Sumarijem yang baru berusia 18 tahun tengah menanti bus di pinggir jalan. Tiba-tiba ia diseret oleh sekelompok pria dan dibius. Selanjutnya ia dibawa ke sebuah rumah di Klaten dan diperkosa secara bergilir hingga tak sadarkan diri. Saat melapor pada polisi, bukannya dibantu Sum malah ditangkap atas tuduhan membuat laporan palsu. Ia mendapat masalah besar karena kasus ini melibatkan anak-anak pejabat sebagai tersangka. Bahkan Jenderal Pur Hoegeng yang merupakan mantan Kapolri yang berusaha mengungkap kasus ini malah dipensiunkan. Banyak orang menduga pensiunnya Hoegeng adalah agar kasus ini segera ditutup. Kasus tersebut merupakan pelanggaran dari Undang-Undang Hak Asasi Manusia yakni...\",\"opsi_a\":\"UU No. 40 Tahun 1999\",\"opsi_b\":\"UU No. 38 Tahun 2000\",\"opsi_c\":\"UU No. 39 Tahun 1999\",\"opsi_d\":\"UU No. 37 Tahun 1998\",\"opsi_e\":\"UU No. 36 Tahun 1997\",\"jawaban_benar\":\"C\",\"kategori_id\":\"1\",\"nomor\":4,\"kategori\":\"TWK\"},{\"id\":\"7891\",\"pertanyaan\":\"Setelah pendirian BPUPKI dan berjalan lahirlah Piagam Jakarta pada tanggal...\",\"opsi_a\":\"1 Maret 1945\",\"opsi_b\":\"29 Mei 1945\",\"opsi_c\":\"1 Juni 1945\",\"opsi_d\":\"22 Juni 1945\",\"opsi_e\":\"\",\"jawaban_benar\":\"D\",\"kategori_id\":\"1\",\"nomor\":5,\"kategori\":\"TWK\"},{\"id\":\"1434\",\"pertanyaan\":\"Pasal 14 ayat (2) UUD 1945 menyatakan bahwa Presiden memberikan amnesti dan abolisi dengan pertimbangan dari suatu lembaga negara. Dalam konteks era sekarang, bagaimana mekanisme ini berperan dalam menjaga keadilan dan hukum di Indonesia?\",\"opsi_a\":\"Pertimbangan Mahkamah Agung memastikan bahwa keputusan amnesti dan abolisi sesuai dengan hukum\",\"opsi_b\":\"Pertimbangan Dewan Perwakilan Rakyat memastikan transparansi dan akuntabilitas dalam pemberian amnesti dan abolisi\",\"opsi_c\":\"Pertimbangan Komisi Yudisial memastikan integritas dan profesionalisme hakim dalam kasus amnesti dan abolisi\",\"opsi_d\":\"Pertimbangan Kementerian Hukum dan HAM memastikan bahwa keputusan amnesti dan abolisi sejalan dengan kebijakan penegakan hukum\",\"opsi_e\":\"Pertimbangan Kejaksaan Agung memastikan bahwa keputusan amnesti dan abolisi tidak mengganggu proses peradilan yang sedang berjalan\",\"jawaban_benar\":\"B\",\"kategori_id\":\"1\",\"nomor\":6,\"kategori\":\"TWK\"},{\"id\":\"4079\",\"pertanyaan\":\"Pergantian sistem pemerintahan yang berlaku di Indonesia pada tahun 1945 didasarkan pada...\",\"opsi_a\":\"Maklumat Wakil Presiden Nomor IX Tanggal 16 Oktober 1945\",\"opsi_b\":\"Maklumat Wakil Presiden Nomor XI Tanggal 16 Oktober 1945\",\"opsi_c\":\"Maklumat Pemerintah Tanggal 3 November 1945\",\"opsi_d\":\"Maklumat Pemerintah Tanggal 14 November 1945\",\"opsi_e\":\"\",\"jawaban_benar\":\"D\",\"kategori_id\":\"1\",\"nomor\":7,\"kategori\":\"TWK\"},{\"id\":\"10968\",\"pertanyaan\":\"Untuk penggunaan di lapangan umum ukuran Bendera Sang Merah Putih yang dipakai adalah ... cm.\",\"opsi_a\":\"30 cm x 45 cm\",\"opsi_b\":\"120 cm x 180 cm\",\"opsi_c\":\"36 cm x 54 cm\",\"opsi_d\":\"200 cm x 300 cm\",\"opsi_e\":\"100 cm x 150 cm\",\"jawaban_benar\":\"B\",\"kategori_id\":\"1\",\"nomor\":8,\"kategori\":\"TWK\"},{\"id\":\"6263\",\"pertanyaan\":\"Pancasila sebagai dasar negara diresmikan pada tanggal...\",\"opsi_a\":\"17 Agustus 1945\",\"opsi_b\":\"1 Juni 1945\",\"opsi_c\":\"18 Agustus 1945\",\"opsi_d\":\"22 Juni 1945\",\"opsi_e\":\"18 Agustus 1945\",\"jawaban_benar\":\"B\",\"kategori_id\":\"1\",\"nomor\":9,\"kategori\":\"TWK\"},{\"id\":\"5827\",\"pertanyaan\":\"Wawasan Nusantara sebagai pedoman bagi perwujudan cita-cita dan mencapai tujuan nasional dalam kehidupan berbangsa dan bernegara mempunyai fungsi ke dalam yaitu:\",\"opsi_a\":\"Ingin melaksanakan ketertiban dunia\",\"opsi_b\":\"Ingin mencerdaskan kehidupan bangsa\",\"opsi_c\":\"Ingin mewujudkan kesatuan dalam berbagai aspek alamiah dan aspek sosial\",\"opsi_d\":\"Ingin mewujudkan kesejahteraan ekonomi seluruh rakyat\",\"opsi_e\":\"Ingin mewujudkan masyarakat adil makmur\",\"jawaban_benar\":\"C\",\"kategori_id\":\"1\",\"nomor\":10,\"kategori\":\"TWK\"},{\"id\":\"10467\",\"pertanyaan\":\"Pedoman Penghayatan dan Pengamalan Pancasila ditetapkan pada tanggal...\",\"opsi_a\":\"4 Maret 1978\",\"opsi_b\":\"22 Maret 1978\",\"opsi_c\":\"12 Maret 1978\",\"opsi_d\":\"14 Maret 2978\",\"opsi_e\":\"2 Maret 1978\",\"jawaban_benar\":\"B\",\"kategori_id\":\"1\",\"nomor\":11,\"kategori\":\"TWK\"},{\"id\":\"12933\",\"pertanyaan\":\"Di lingkungan yang multikultural sering terdengar perbincangan yang diwarnai logat khas daerah masing-masing. Pemaknaan atas peristiwa tersebut dalam kerangka bhineka tunggal ika adalah...\",\"opsi_a\":\"Tiap-tiap budaya memiliki kekayaan berbahasa yang diapresiasi\",\"opsi_b\":\"Keragaman logat perbincangan menjadi kekayaan untuk saling memahami\",\"opsi_c\":\"Perlu logat bahasa standar agar Indonesia menjadi satu aksi berbahasa\",\"opsi_d\":\"Perbincangan yang menjadi cerminan multikultural tersebut bisa menjadi aset nasional\",\"opsi_e\":\"Lingkungan multikultural rentan praktik perundungan karena ada yang dianggap orang kampung\",\"jawaban_benar\":\"B\",\"kategori_id\":\"1\",\"nomor\":12,\"kategori\":\"TWK\"},{\"id\":\"7565\",\"pertanyaan\":\"Dalam rapat BPUPKI yang membahas rancangan undang-undang dasar, permasalahan bentuk negara menjadi salah satu pembahasan yang diperbedatkan secara serius. Usulan bentuk negara yang muncul pada waktu itu, yaitu negara kesatuan dan negara federal. Namun kemudian disepakati bentuk Negara Indonesia ialah negara kesatuan, sebagaimana tertera dalam Pasal 1 ayat (1) Undang-Undang Dasar 1945. Mengapa negara kesatuan lebih cocok sebagai bentuk negara Indonesia?\",\"opsi_a\":\"Indonesia sangat heterogen dan bentuk negara kesatuan bisa merangkul seluruh perbedaan tersebut sekaligus memastikan pengambilan kebijakan yang adil untuk setiap daerah, serta memperkecil risiko perpecahan karena otonomi yang berlebihan.\",\"opsi_b\":\"Indonesia terdiri dari puluhan ribu pulau yang terbentang dari Sabang-Merauke dimana setiap pulaunya memiliki karakteristik tersendiri sehingga setiap wilayah perlu memiliki pemerintahan dan otonominya sendiri.\",\"opsi_c\":\"Indonesia merupakan negara yang sangat heterogen dengan beragam suku, budaya, dan agama sehingga diperlukan adanya kekuasaan tunggal yang tidak dapat diganggu gugat.\",\"opsi_d\":\"Indonesia harus bisa menyeimbangkan kepentingan nasional dan lokal, serta memberikan otonomi yang lebih besar bagi daerah.\",\"opsi_e\":\"Indonesia pada masa itu baru merdeka dan para founding fathers ingin mencegah lahirnya kelas borjuis dari penjajahan dan kelas proletar dari pihak terjajah.\",\"jawaban_benar\":\"A\",\"kategori_id\":\"1\",\"nomor\":13,\"kategori\":\"TWK\"},{\"id\":\"978\",\"pertanyaan\":\"Pancasila sebagai dasar negara Indonesia memainkan peran penting dalam memperkuat persatuan dan kesatuan bangsa. Bagaimana Pancasila sebagai dasar negara Indonesia memperkuat persatuan dan kesatuan bangsa?\",\"opsi_a\":\"Mendorong masyarakat untuk menghargai keberagaman budaya\",\"opsi_b\":\"Menjadi pedoman dalam pembuatan undang-undang yang adil\",\"opsi_c\":\"Membentuk identitas nasional yang kuat dan bersatu\",\"opsi_d\":\"Menyediakan kerangka moral untuk perilaku warga negara\",\"opsi_e\":\"Mengarahkan pembangunan nasional yang berkelanjutan\",\"jawaban_benar\":\"C\",\"kategori_id\":\"1\",\"nomor\":14,\"kategori\":\"TWK\"},{\"id\":\"15106\",\"pertanyaan\":\"Integrasi nasional seharusnya dimulai dari pejabat negara sehingga bisa memberikan contoh bagi warga negara. Salah satu tindakan pejabat negara yang tidak mendukung integritas negara adalah praktik korupsi. Komisi Pemberantasan Korupsi (KPK) merupakan lembaga negara yang dibentuk untuk menyelidiki kasus kejahatan luar biasa korupsi, kolusi, dan nepotisme(KKN). Berbagai kasus korupsi mencuat ke permukaan. KPK berhasil mengungkap dan menangkap pelakunya. Akan tetapi, kasus korupsi masih marak terjadi. Upaya paling tepat yang dapat dilakukan masyarakat untuk menghentikan praktik kejahatan luar biasa tersebut adalah ....\",\"opsi_a\":\"Menjatuhkan sanksi berat terhadap terdakwa kasus korupsi\",\"opsi_b\":\"Menegakkan hukum setegak-tegaknya tanpa pandang bulu\",\"opsi_c\":\"Melakukan sosialisasi terkait tindak pidana korupsi dan dampaknya\",\"opsi_d\":\"Mengembangkan sikap sadar hukum dalam kehidupan mulai dari lingkungan terkecil\",\"opsi_e\":\"Membuat peraturan perundang-undangan tanpa memberi celah untuk berkembangnya praktik korupsi.\",\"jawaban_benar\":\"B\",\"kategori_id\":\"1\",\"nomor\":15,\"kategori\":\"TWK\"},{\"id\":\"979\",\"pertanyaan\":\"Banyak korban musibah longsor yang terjadi di Indonesia mendorong kita untuk bersatu dan saling menolong. Apa dampak sosial utama jika kita tidak membantu korban bencana tersebut?\",\"opsi_a\":\"Menurunnya semangat gotong-royong dalam masyarakat\",\"opsi_b\":\"Korban longsor akan kesulitan mendapatkan bantuan yang mereka butuhkan\",\"opsi_c\":\"Menurunnya rasa kemanusiaan dalam masyarakat\",\"opsi_d\":\"Meningkatkan ketegangan sosial di masyarakat\",\"opsi_e\":\"Menurunnya rasa kepedulian terhadap sesama\",\"jawaban_benar\":\"A\",\"kategori_id\":\"1\",\"nomor\":16,\"kategori\":\"TWK\"},{\"id\":\"1278\",\"pertanyaan\":\"Tanggal berapa proklamasi kemerdekaan Indonesia diumumkan?\",\"opsi_a\":\"17 Agustus 1945\",\"opsi_b\":\"1 Juni 1945\",\"opsi_c\":\"18 Agustus 1945\",\"opsi_d\":\"22 Juni 1945\",\"opsi_e\":\"\",\"jawaban_benar\":\"A\",\"kategori_id\":\"1\",\"nomor\":17,\"kategori\":\"TWK\"},{\"id\":\"13677\",\"pertanyaan\":\"Di bawah ini adalah salah satu contoh perilaku sebagai perwujudan sikap nasionalisme warga negara dalam UUD Negara RI tahun 1945...\",\"opsi_a\":\"Membantu pihak kepolisian untuk menangkap dan menghakimi pencuri yang tertangkap\",\"opsi_b\":\"Menjadi distributor hasil pertanian untuk pedagang dalam rangka meningkatkan kesejahteraan\",\"opsi_c\":\"Mencoba bertahan hidup di ibu kota dengan mengamen di bus kota dan perempatan jalan\",\"opsi_d\":\"Mengembangkan dan mempromosikan budaya daerah sehingga daerah itu dikenal di kancah nasional dan internasional\",\"opsi_e\":\"Ikut aktif menjadi anggota kelompok seni budaya yang telah dirintis oleh keluarga karena hal itu menjadi sumber kehidupan satu-satunya\",\"jawaban_benar\":\"D\",\"kategori_id\":\"1\",\"nomor\":18,\"kategori\":\"TWK\"},{\"id\":\"3812\",\"pertanyaan\":\"Contoh pengamalan Pancasila sebagai pandangan hidup bangsa berdasarkan sila keempat adalah ...\",\"opsi_a\":\"Memperlakukan sesama secara adil dan beradab\",\"opsi_b\":\"Saling menghormati antar pemeluk agama\",\"opsi_c\":\"Menumbuhkan sikap hidup tolong menolong\",\"opsi_d\":\"Menjunjung tinggi asas kerakyatan\",\"opsi_e\":\"Menempatkan kepentingan umum di atas kepentingan pribadi\",\"jawaban_benar\":\"D\",\"kategori_id\":\"1\",\"nomor\":19,\"kategori\":\"TWK\"}