(1354, 2, NULL, NULL, NULL, 'Hutan : Pohon = Gurun : ...', 'Panas', 'Dingin', 'Batu', 'Pasir', 'Luas', 'D', 'Hutan ditumbuhi pohon, Gurun ditutupi pasir. Hubungan: Tempat : Ciri khas utama.', 'Untuk analogi geografis, identifikasi hubungan tempat dengan ciri khasnya.', '2026-05-09 19:03:25', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0),
(1363, 2, NULL, NULL, NULL, '23 22 S R 19 18 O N 15 14...', 'H', 'I', 'J', 'K', 'L', 'D', '23=W, 22=V, 21=U, 20=T, 19=S, 18=R, 17=Q, 16=O, 15=N, 14=M, 13=L, 12=K. Pola: -1 huruf.', 'Untuk deret huruf, gunakan urutan alfabet terbalik untuk mencari pola.', '2026-05-09 19:03:25', 'sedang', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0),
