INSERT INTO `tips_tricks` (`id`, `kategori_id`, `tipe_tips`, `judul`, `konten`, `contoh`, `prioritas`, `aktif`, `created_at`) VALUES
(1, 1, 'umum', 'Tips Menjawab TWK', 'Baca soal dengan teliti dan pahami konteks sejarah dan ideologi bangsa', 'Selalu kaitkan dengan Pancasila dan UUD 1945', 1, 1, '2026-05-12 01:36:34'),
(2, 1, 'strategi', 'Strategi TWK', 'Fokus pada materi sejarah, geografi, dan ideologi negara', 'Pelajari pahlawan nasional dan peristiwa penting', 2, 1, '2026-05-12 01:36:34'),
(3, 2, 'umum', 'Tips Menjawab TIU', 'Gunakan logika matematika dan pola untuk mempercepat penyelesaian', 'Gunakan teknik eliminasi untuk opsi yang jelas salah', 1, 1, '2026-05-12 01:36:34'),
(4, 2, 'shortcut', 'Shortcut TIU', 'Untuk soal deret, cari pola selisih antar angka', 'Contoh: 2,4,6,8 selisihnya 2, angka berikutnya 10', 3, 1, '2026-05-12 01:36:34'),
(5, 3, 'umum', 'Tips Menjawab TKP', 'Jawab sesuai kepribadian dan karakter Anda yang sebenarnya', 'Jangan pura-pura, sistem akan mendeteksi ketidakkonsistenan', 1, 1, '2026-05-12 01:36:34'),
(6, 3, 'strategi', 'Strategi TKP', 'Pahami skala penilaian (1-5) dan konteks situasi kerja', 'Nilai 5 = Sangat Sesuai, Nilai 1 = Sangat Tidak Sesuai', 2, 1, '2026-05-12 01:36:34'),
(7, 3, 'spesifik', 'Tips Soal TKP (mudah) - #7686', 'Tips untuk menjawab soal tingkat mudah:
INSERT INTO `tips_umum` (`id`, `kategori_id`, `judul`, `konten`, `created_at`) VALUES
(6, 1, 'Tips TWK - Pahami Konsep', 'Untuk soal TWK, pahami konsep dasar nasionalisme, integritas, dan bela negara. Baca dengan teliti setiap pertanyaan karena seringkali ada jebakan dalam pemilihan kata.', '2026-05-09 18:28:12'),
(13, 3, 'Tips TKP - Jujur pada Diri Sendiri', 'Soal TKP mengukur kepribadian Anda. Jawablah dengan jujur sesuai dengan karakter Anda. Jangan mencoba menebak jawaban yang dianggap \"benar\" karena sistem penilaian TKP berbeda dengan TWK dan TIU.', '2026-05-09 23:21:38'),
(14, 4, 'Tips TPA - Latihan Rutin', 'TPA menguji potensi akademik Anda. Latihan soal secara rutin akan membantu meningkatkan kecepatan dan akurasi dalam mengerjakan soal bahasa, numerik, dan logika.', '2026-05-09 23:21:38'),
(15, 5, 'Tips Psikologis - Tenang dan Waspada', 'Tes psikologis mengukur kepribadian dan motivasi Anda. Tetaplah tenang dan wasapda saat mengerjakan. Jawablah sesuai dengan perasaan dan pemikiran Anda yang sebenarnya.', '2026-05-09 23:21:38'),
(16, 4, 'Tips TPA - Manajemen Waktu', 'Bagi waktu secara proporsional untuk setiap jenis soal TPA. Jangan terjebak terlalu lama pada satu soal yang sulit. Lewati dan kembali lagi jika ada waktu sisa.', '2026-05-09 23:21:38'),
(17, 5, 'Tips Psikologis - Konsistensi', 'Jawablah soal psikologis dengan konsisten. Jangan berpindah sikap di tengah tes karena ini dapat mempengaruhi hasil penilaian kepribadian Anda.', '2026-05-09 23:21:38'),
(29, NULL, 'Tips Deret Angka', 'Trik \"Hitung Detik\" untuk deret angka:
