(39540, 420, 'Sekuler >< ...', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #420', '', 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_420_1778530107.html', 0, 'B', 'Sekuler berarti duniawi atau non-keagamaan, lawan katanya adalah keagamaan.'),
(5554, 423, '1, 5, 11, 19, 29, ..., 55', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #423', '', 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_423_1778528051.html', 0, 'B', 'Pola: +4, +6, +8, +10, +12, +16. 29+12=41, 41+16=57 (bukan 55). Cek ulang: 1+4=5, 5+6=11, 11+8=19, 19+10=29, 29+12=41, 41+14=55. Pola: selisih bertambah 2. 41+14=55.'),
(29942, 423, '1, 5, 11, 19, 29, ..., 55', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #423', '', 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_423_1778529848.html', 0, 'B', 'Pola: +4, +6, +8, +10, +12, +16. 29+12=41, 41+16=57 (bukan 55). Cek ulang: 1+4=5, 5+6=11, 11+8=19, 19+10=29, 29+12=41, 41+14=55. Pola: selisih bertambah 2. 41+14=55.'),
(12182, 448, 'Galib = ...', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #448', '', 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_448_1778528233.html', 0, 'D', 'Galib berarti umum atau biasa. Sinonim.'),
