(37652, 6176, 'Nelayan : perahu = ... : ...', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #6176', '', 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_6176_1778530065.html', 0, 'C', 'Nelayan menggunakan perahu sebagai alat kerja, sama seperti petani menggunakan traktor sebagai alat kerja.'),
(23277, 6177, 'Panggung : aktor = ... : ...', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #6177', '', 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_6177_1778529669.html', 0, 'C', 'Panggung adalah tempat aktor bekerja, sama seperti ring adalah tempat petinju bertanding.'),
(7998, 6178, 'Pop : Musik = ... : ...', 2, 'TIU', 'Materi Pembelajaran: TIU - Soal #6178', '', 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_6178_1778528123.html', 0, 'A', 'Pop adalah genre musik, sama seperti Farmakologi adalah ilmu tentang obat.'),
