(3341, 10202, 'UUD 1945 sebelum diamandemen menyatakan bahwa kedaulatan diatur oleh rakyat dan dilakukan sepenuhnya oleh …', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #10202', '', 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_10202_1778527976.html', 0, 'D', 'UUD 1945 sebelum diamandemen menyatakan kedaulatan dilakukan sepenuhnya oleh MPR.'),
(5823, 10203, 'Amandemen kedua UUD 1945 mengubah beberapa pasal, kecuali …', 1, 'TWK', 'Materi Pembelajaran: TWK - Soal #10203', '', 'teks', NULL, 'uploads/bahan_pelajaran/text/materi_10203_1778528064.html', 0, 'C', 'Amandemen kedua UUD 1945 tidak mengubah Pasal 24.'),
