CREATE TABLE `achievements` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `nama` varchar(255) NOT NULL,
  `deskripsi` text DEFAULT NULL,
  `kategori` varchar(100) DEFAULT NULL,
  `xp_reward` int(11) DEFAULT 0,
  `badge_id` int(11) DEFAULT NULL,
  `criteria_type` varchar(100) DEFAULT NULL,
  `criteria_value` int(11) DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT 1,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `badge_id` (`badge_id`),
  CONSTRAINT `achievements_ibfk_1` FOREIGN KEY (`badge_id`) REFERENCES `badges` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=31 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


CREATE TABLE `ai_generated_questions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `tryout_session_id` int(11) DEFAULT NULL,
  `topic_id` int(11) DEFAULT NULL,
  `kategori_id` int(11) DEFAULT NULL,
  `pertanyaan` text DEFAULT NULL,
  `opsi_a` text DEFAULT NULL,
  `opsi_b` text DEFAULT NULL,
  `opsi_c` text DEFAULT NULL,
  `opsi_d` text DEFAULT NULL,
  `opsi_e` text DEFAULT NULL,
  `jawaban_benar` varchar(10) DEFAULT NULL,
  `pembahasan` text DEFAULT NULL,
  `expert_tips` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`expert_tips`)),
  `difficulty` enum('mudah','sedang','sulit') DEFAULT 'sedang',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `tryout_session_id` (`tryout_session_id`),
  CONSTRAINT `ai_generated_questions_ibfk_1` FOREIGN KEY (`tryout_session_id`) REFERENCES `tryout_sessions` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `analisis_kelemahan` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) DEFAULT NULL,
  `sesi_id` int(11) DEFAULT NULL,
  `kategori_id` int(11) DEFAULT NULL,
  `total_soal` int(11) DEFAULT 0,
  `benar` int(11) DEFAULT 0,
  `salah` int(11) DEFAULT 0,
  `kosong` int(11) DEFAULT 0,
  `persen_benar` decimal(5,2) DEFAULT 0.00,
  `tingkat_kelemahan` enum('rendah','sedang','tinggi','sangat_tinggi') DEFAULT 'sedang',
  `rekomendasi` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_user_kategori` (`user_id`,`kategori_id`),
  KEY `sesi_id` (`sesi_id`),
  KEY `kategori_id` (`kategori_id`),
  KEY `idx_analisis_user_kategori` (`user_id`,`kategori_id`),
  CONSTRAINT `analisis_kelemahan_ibfk_3` FOREIGN KEY (`kategori_id`) REFERENCES `kategori_soal` (`id`),
  CONSTRAINT `fk_analisis_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=35 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE `answer_heatmap` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `question_id` int(11) NOT NULL,
  `option_a_count` int(11) DEFAULT 0,
  `option_b_count` int(11) DEFAULT 0,
  `option_c_count` int(11) DEFAULT 0,
  `option_d_count` int(11) DEFAULT 0,
  `option_e_count` int(11) DEFAULT 0,
  `correct_option` varchar(1) DEFAULT NULL,
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_answer_heatmap_question` (`question_id`),
  CONSTRAINT `answer_heatmap_ibfk_1` FOREIGN KEY (`question_id`) REFERENCES `soal` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `badges` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `nama` varchar(255) NOT NULL,
  `deskripsi` text DEFAULT NULL,
  `icon` varchar(100) DEFAULT NULL,
  `kategori` varchar(100) DEFAULT NULL,
  `xp_reward` int(11) DEFAULT 0,
  `is_active` tinyint(1) DEFAULT 1,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=25 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


CREATE TABLE `bahan_pelajaran` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `soal_id` int(11) DEFAULT NULL,
  `kategori_id` int(11) DEFAULT NULL,
  `judul` varchar(255) DEFAULT NULL,
  `konten` longtext DEFAULT NULL,
  `tipe` enum('teks','video','pdf','link') DEFAULT 'teks',
  `url` varchar(500) DEFAULT NULL,
  `file_path` varchar(255) DEFAULT NULL,
  `urutan` int(11) DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `soal_id` (`soal_id`),
  KEY `idx_kategori` (`kategori_id`),
  KEY `idx_bahan_soal` (`soal_id`),
  KEY `idx_bahan_judul` (`judul`(100)),
  KEY `idx_bahan_tipe` (`tipe`),
  KEY `idx_bahan_created` (`created_at`),
  CONSTRAINT `bahan_pelajaran_ibfk_1` FOREIGN KEY (`soal_id`) REFERENCES `soal` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=41658 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE `content_versions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `content_type` enum('materi','tips','soal','course') NOT NULL,
  `content_id` int(11) NOT NULL,
  `version_number` int(11) NOT NULL,
  `content` text NOT NULL,
  `author_id` int(11) NOT NULL,
  `change_summary` text DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_content_versions_content` (`content_type`,`content_id`),
  KEY `idx_content_versions_author` (`author_id`),
  CONSTRAINT `content_versions_ibfk_1` FOREIGN KEY (`author_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `course_materials` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `module_id` int(11) NOT NULL,
  `judul` varchar(255) NOT NULL,
  `konten` text DEFAULT NULL,
  `tipe` enum('teks','video','pdf','audio','quiz') DEFAULT 'teks',
  `file_path` varchar(500) DEFAULT NULL,
  `urutan` int(11) DEFAULT 0,
  `soal_id` int(11) DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `soal_id` (`soal_id`),
  KEY `idx_course_materials_module` (`module_id`),
  CONSTRAINT `course_materials_ibfk_1` FOREIGN KEY (`module_id`) REFERENCES `course_modules` (`id`) ON DELETE CASCADE,
  CONSTRAINT `course_materials_ibfk_2` FOREIGN KEY (`soal_id`) REFERENCES `soal` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `course_modules` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `course_id` int(11) NOT NULL,
  `judul` varchar(255) NOT NULL,
  `deskripsi` text DEFAULT NULL,
  `urutan` int(11) DEFAULT 0,
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_course_modules_course` (`course_id`),
  CONSTRAINT `course_modules_ibfk_1` FOREIGN KEY (`course_id`) REFERENCES `courses` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `course_prerequisites` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `course_id` int(11) NOT NULL,
  `prerequisite_course_id` int(11) NOT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_prereq` (`course_id`,`prerequisite_course_id`),
  KEY `prerequisite_course_id` (`prerequisite_course_id`),
  CONSTRAINT `course_prerequisites_ibfk_1` FOREIGN KEY (`course_id`) REFERENCES `courses` (`id`) ON DELETE CASCADE,
  CONSTRAINT `course_prerequisites_ibfk_2` FOREIGN KEY (`prerequisite_course_id`) REFERENCES `courses` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `courses` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `judul` varchar(255) NOT NULL,
  `deskripsi` text DEFAULT NULL,
  `kategori` varchar(100) DEFAULT NULL,
  `tags` varchar(500) DEFAULT NULL,
  `urutan` int(11) DEFAULT 0,
  `status` enum('draft','published','archived') DEFAULT 'draft',
  `created_by` int(11) DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `created_by` (`created_by`),
  KEY `idx_courses_kategori` (`kategori`),
  KEY `idx_courses_status` (`status`),
  KEY `idx_courses_created` (`created_at`),
  CONSTRAINT `courses_ibfk_1` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `daily_challenges` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `judul` varchar(255) NOT NULL,
  `deskripsi` text DEFAULT NULL,
  `challenge_type` varchar(100) DEFAULT NULL,
  `target_value` int(11) NOT NULL,
  `xp_reward` int(11) DEFAULT 0,
  `date` date NOT NULL,
  `is_active` tinyint(1) DEFAULT 1,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_daily_challenge` (`date`,`challenge_type`),
  KEY `idx_daily_challenges_date` (`date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `exam_analytics` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `exam_id` int(11) DEFAULT NULL,
  `category` varchar(10) DEFAULT NULL,
  `total_participants` int(11) DEFAULT 0,
  `avg_score` decimal(5,2) DEFAULT 0.00,
  `pass_rate` decimal(5,2) DEFAULT 0.00,
  `avg_time_minutes` decimal(10,2) DEFAULT 0.00,
  `drop_off_rate` decimal(5,2) DEFAULT 0.00,
  `date` date DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_exam_analytics_date` (`date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `exam_reminders` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `exam_id` int(11) DEFAULT NULL,
  `reminder_type` enum('before','after') DEFAULT 'before',
  `hours_before` int(11) DEFAULT NULL,
  `scheduled_at` datetime NOT NULL,
  `sent_at` datetime DEFAULT NULL,
  `status` enum('pending','sent','skipped','failed') DEFAULT 'pending',
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_exam_reminders_user` (`user_id`),
  KEY `idx_exam_reminders_scheduled` (`scheduled_at`),
  KEY `idx_exam_reminders_status` (`status`),
  CONSTRAINT `exam_reminders_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `exam_types` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `code` varchar(20) NOT NULL,
  `name` varchar(100) NOT NULL,
  `description` text DEFAULT NULL,
  `icon` varchar(50) DEFAULT 'fa-file-alt',
  `color` varchar(20) DEFAULT '#1e40af',
  `is_active` tinyint(1) DEFAULT 1,
  `passing_grade_twk` int(11) DEFAULT 15,
  `passing_grade_tiu` int(11) DEFAULT 15,
  `passing_grade_tkp` int(11) DEFAULT 15,
  `passing_grade_tpa` int(11) DEFAULT 10,
  `passing_grade_psikologis` int(11) DEFAULT 10,
  `passing_grade_total` int(11) DEFAULT 40,
  `durasi_menit` int(11) DEFAULT 100,
  `jumlah_soal` int(11) DEFAULT 20,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `code` (`code`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


CREATE TABLE `expert_assistance_log` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) DEFAULT NULL,
  `soal_id` int(11) DEFAULT NULL,
  `expert_knowledge_id` int(11) DEFAULT NULL,
  `jenis_bantuan` enum('trik','tips','pembahasan','metode_cepat') DEFAULT NULL,
  `rating` tinyint(1) DEFAULT NULL,
  `feedback` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`),
  KEY `soal_id` (`soal_id`),
  KEY `expert_knowledge_id` (`expert_knowledge_id`),
  CONSTRAINT `expert_assistance_log_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`),
  CONSTRAINT `expert_assistance_log_ibfk_2` FOREIGN KEY (`soal_id`) REFERENCES `soal` (`id`),
  CONSTRAINT `expert_assistance_log_ibfk_3` FOREIGN KEY (`expert_knowledge_id`) REFERENCES `expert_knowledge` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


CREATE TABLE `expert_knowledge` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `kategori_id` int(11) NOT NULL,
  `sub_kategori` varchar(100) DEFAULT NULL,
  `jenis_pengetahuan` enum('trik','tips','metode_cepat','logika','pembahasan') NOT NULL,
  `judul` varchar(255) NOT NULL,
  `konten` text NOT NULL,
  `contoh_soal` text DEFAULT NULL,
  `contoh_penyelesaian` text DEFAULT NULL,
  `kunci_kata` varchar(255) DEFAULT NULL,
  `tingkat_kesulitan` enum('mudah','sedang','sulit') DEFAULT NULL,
  `prioritas` int(11) DEFAULT 0,
  `is_active` tinyint(1) DEFAULT 1,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `kategori_id` (`kategori_id`),
  CONSTRAINT `expert_knowledge_ibfk_1` FOREIGN KEY (`kategori_id`) REFERENCES `expert_knowledge_category` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=79 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


CREATE TABLE `expert_knowledge_category` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `nama_kategori` varchar(100) NOT NULL,
  `deskripsi` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


CREATE TABLE `expert_learning_recommendation` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) DEFAULT NULL,
  `kategori_kelemahan` varchar(100) DEFAULT NULL,
  `expert_knowledge_id` int(11) DEFAULT NULL,
  `prioritas` int(11) DEFAULT 0,
  `status` enum('pending','in_progress','completed') DEFAULT 'pending',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `completed_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`),
  KEY `expert_knowledge_id` (`expert_knowledge_id`),
  CONSTRAINT `expert_learning_recommendation_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`),
  CONSTRAINT `expert_learning_recommendation_ibfk_2` FOREIGN KEY (`expert_knowledge_id`) REFERENCES `expert_knowledge` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `funnel_analytics` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `stage` enum('landing','signup','dashboard','exam_start','exam_complete','certificate_download') DEFAULT NULL,
  `timestamp` datetime DEFAULT current_timestamp(),
  `metadata` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`metadata`)),
  PRIMARY KEY (`id`),
  KEY `idx_funnel_analytics_user` (`user_id`),
  KEY `idx_funnel_analytics_timestamp` (`timestamp`),
  CONSTRAINT `funnel_analytics_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


CREATE TABLE `hasil_ujian` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `nama_peserta` varchar(100) NOT NULL,
  `user_id` int(11) DEFAULT NULL,
  `tanggal_ujian` datetime DEFAULT current_timestamp(),
  `durasi_menit` int(11) NOT NULL,
  `nilai_twk` int(11) DEFAULT 0,
  `nilai_tiu` int(11) DEFAULT 0,
  `nilai_tkp` int(11) DEFAULT 0,
  `nilai_tpa` int(11) DEFAULT 0,
  `nilai_psikologis` int(11) DEFAULT 0,
  `nilai_total` int(11) DEFAULT 0,
  `status_lulus` varchar(20) DEFAULT 'TIDAK LULUS',
  `jawaban_peserta` text DEFAULT NULL,
  `verification_code` varchar(32) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `verification_code` (`verification_code`),
  KEY `idx_hasil_user` (`user_id`),
  KEY `idx_hasil_tanggal` (`tanggal_ujian`),
  KEY `idx_hasil_ujian_user` (`user_id`),
  KEY `idx_hasil_ujian_tanggal` (`tanggal_ujian`),
  KEY `idx_hasil_ujian_user_tanggal` (`user_id`,`tanggal_ujian`),
  CONSTRAINT `fk_hasil_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=31 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Indexes added for user history, status filtering, and verification lookup';


CREATE TABLE `kategori_soal` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `nama_kategori` varchar(50) NOT NULL,
  `deskripsi` text DEFAULT NULL,
  `default_learning_topic_id` int(11) DEFAULT NULL,
  `materi_description` text DEFAULT NULL,
  `passing_grade` int(11) DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE `leaderboard_optout` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `nama_peserta` varchar(100) DEFAULT NULL,
  `opted_out_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_leaderboard_nama` (`nama_peserta`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `learning_path_courses` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `learning_path_id` int(11) NOT NULL,
  `course_id` int(11) NOT NULL,
  `urutan` int(11) DEFAULT 0,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_path_course` (`learning_path_id`,`course_id`),
  KEY `course_id` (`course_id`),
  CONSTRAINT `learning_path_courses_ibfk_1` FOREIGN KEY (`learning_path_id`) REFERENCES `learning_paths` (`id`) ON DELETE CASCADE,
  CONSTRAINT `learning_path_courses_ibfk_2` FOREIGN KEY (`course_id`) REFERENCES `courses` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `learning_paths` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `judul` varchar(255) NOT NULL,
  `deskripsi` text DEFAULT NULL,
  `min_score_twk` decimal(5,2) DEFAULT NULL,
  `min_score_tiu` decimal(5,2) DEFAULT NULL,
  `min_score_tkp` decimal(5,2) DEFAULT NULL,
  `min_score_tpa` decimal(5,2) DEFAULT NULL,
  `min_score_psikologis` decimal(5,2) DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `created_by` (`created_by`),
  KEY `idx_learning_paths_min_scores` (`min_score_twk`,`min_score_tiu`,`min_score_tkp`),
  CONSTRAINT `learning_paths_ibfk_1` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `learning_recommendations` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `topic_id` int(11) NOT NULL,
  `recommendation_type` varchar(50) DEFAULT 'study',
  `reason` text DEFAULT NULL,
  `priority` int(11) DEFAULT 0,
  `status` enum('pending','in_progress','completed','dismissed') DEFAULT 'pending',
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_topic_id` (`topic_id`),
  KEY `idx_learning_recommendations_user` (`user_id`),
  KEY `idx_learning_recommendations_topic` (`topic_id`),
  KEY `idx_learning_recommendations_status` (`status`),
  KEY `idx_learning_recommendations_priority` (`priority`),
  KEY `idx_learning_recommendations_type` (`recommendation_type`)
) ENGINE=InnoDB AUTO_INCREMENT=43 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


CREATE TABLE `learning_topics` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `topic_name` varchar(255) NOT NULL,
  `kategori` varchar(50) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `external_api_url` varchar(500) DEFAULT NULL,
  `json_material_url` varchar(500) DEFAULT NULL,
  `difficulty_level` enum('basic','intermediate','advanced') DEFAULT 'intermediate',
  `estimated_study_time` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


CREATE TABLE `level_rewards` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `level` int(11) NOT NULL,
  `reward_type` varchar(100) DEFAULT NULL,
  `reward_value` int(11) DEFAULT NULL,
  `reward_name` varchar(255) DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_level` (`level`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


CREATE TABLE `notification_preferences` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `email_exam_reminder` tinyint(1) DEFAULT 1,
  `email_exam_result` tinyint(1) DEFAULT 1,
  `email_certificate` tinyint(1) DEFAULT 1,
  `email_achievement` tinyint(1) DEFAULT 1,
  `in_app_exam_reminder` tinyint(1) DEFAULT 1,
  `in_app_exam_result` tinyint(1) DEFAULT 1,
  `in_app_achievement` tinyint(1) DEFAULT 1,
  `push_exam_reminder` tinyint(1) DEFAULT 1,
  `push_exam_result` tinyint(1) DEFAULT 1,
  `sms_exam_reminder` tinyint(1) DEFAULT 0,
  `sms_exam_result` tinyint(1) DEFAULT 0,
  `reminder_hours_before` int(11) DEFAULT 24,
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_user_prefs` (`user_id`),
  KEY `idx_notification_preferences_user` (`user_id`),
  CONSTRAINT `notification_preferences_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


CREATE TABLE `notification_templates` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `category` enum('exam_reminder','exam_result','certificate','system','achievement','challenge','course') NOT NULL,
  `type` enum('email','in_app','push','sms') NOT NULL,
  `subject` varchar(255) DEFAULT NULL,
  `body` text NOT NULL,
  `is_active` tinyint(1) DEFAULT 1,
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


CREATE TABLE `notifications` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `type` enum('email','in_app','push','sms') NOT NULL,
  `title` varchar(255) NOT NULL,
  `message` text NOT NULL,
  `category` enum('exam_reminder','exam_result','certificate','system','achievement','challenge','course') NOT NULL,
  `status` enum('pending','sent','failed') DEFAULT 'pending',
  `sent_at` datetime DEFAULT NULL,
  `error_message` text DEFAULT NULL,
  `metadata` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`metadata`)),
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_notifications_user` (`user_id`),
  KEY `idx_notifications_status` (`status`),
  KEY `idx_notifications_category` (`category`),
  KEY `idx_notifications_created` (`created_at`),
  KEY `idx_notifications_user_status` (`user_id`,`status`),
  CONSTRAINT `notifications_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `paket_blueprint` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `paket_id` int(11) DEFAULT NULL,
  `kategori_id` int(11) DEFAULT NULL,
  `target_count` int(11) DEFAULT 0,
  `min_difficulty` enum('mudah','sedang','sulit') DEFAULT 'sedang',
  `max_difficulty` enum('mudah','sedang','sulit') DEFAULT 'sedang',
  PRIMARY KEY (`id`),
  KEY `paket_id` (`paket_id`),
  KEY `kategori_id` (`kategori_id`),
  CONSTRAINT `paket_blueprint_ibfk_1` FOREIGN KEY (`paket_id`) REFERENCES `paket_tryout` (`id`) ON DELETE CASCADE,
  CONSTRAINT `paket_blueprint_ibfk_2` FOREIGN KEY (`kategori_id`) REFERENCES `kategori_soal` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `paket_tryout` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `nama_paket` varchar(200) NOT NULL,
  `deskripsi` text DEFAULT NULL,
  `durasi` int(11) DEFAULT 100,
  `kategori_id` int(11) DEFAULT NULL,
  `total_soal` int(11) DEFAULT 30,
  `is_active` tinyint(1) DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `kategori_id` (`kategori_id`),
  CONSTRAINT `paket_tryout_ibfk_1` FOREIGN KEY (`kategori_id`) REFERENCES `kategori_soal` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE `participant_learning_progress` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `topic_id` int(11) NOT NULL,
  `status` enum('in_progress','completed') NOT NULL DEFAULT 'in_progress',
  `studied_at` datetime DEFAULT NULL,
  `completion_percentage` int(11) DEFAULT 0,
  `notes` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_user_topic` (`user_id`,`topic_id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_topic_id` (`topic_id`),
  KEY `idx_participant_learning_user` (`user_id`),
  KEY `idx_participant_learning_topic` (`topic_id`),
  KEY `idx_participant_learning_status` (`status`),
  KEY `idx_participant_learning_user_status` (`user_id`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `question_analytics` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `question_id` int(11) NOT NULL,
  `total_attempts` int(11) DEFAULT 0,
  `correct_answers` int(11) DEFAULT 0,
  `incorrect_answers` int(11) DEFAULT 0,
  `skipped_answers` int(11) DEFAULT 0,
  `avg_time_seconds` decimal(10,2) DEFAULT 0.00,
  `difficulty_score` decimal(5,2) DEFAULT 50.00,
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_question_analytics_question` (`question_id`),
  CONSTRAINT `question_analytics_ibfk_1` FOREIGN KEY (`question_id`) REFERENCES `soal` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `question_pattern` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `kategori_soal_id` int(11) DEFAULT NULL,
  `tipe_pertanyaan` varchar(100) DEFAULT NULL,
  `pola_kata` varchar(255) DEFAULT NULL,
  `expert_knowledge_id` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `kategori_soal_id` (`kategori_soal_id`),
  KEY `expert_knowledge_id` (`expert_knowledge_id`),
  CONSTRAINT `question_pattern_ibfk_1` FOREIGN KEY (`kategori_soal_id`) REFERENCES `kategori_soal` (`id`),
  CONSTRAINT `question_pattern_ibfk_2` FOREIGN KEY (`expert_knowledge_id`) REFERENCES `expert_knowledge` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=46 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


CREATE TABLE `rekomendasi_belajar` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) DEFAULT NULL,
  `sesi_id` int(11) DEFAULT NULL,
  `soal_id` int(11) DEFAULT NULL,
  `alasan` enum('salah','ragu','review') NOT NULL,
  `status` enum('pending','dipelajari','dikuasai') DEFAULT 'pending',
  `dipelajari_pada` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `soal_id` (`soal_id`),
  KEY `idx_rekomendasi_user_sesi` (`user_id`,`sesi_id`),
  CONSTRAINT `fk_rekomendasi_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `sertifikat` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) DEFAULT NULL,
  `hasil_id` int(11) DEFAULT NULL,
  `verification_code` varchar(32) DEFAULT NULL,
  `qr_code` text DEFAULT NULL,
  `issued_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `expires_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `verification_code` (`verification_code`),
  KEY `hasil_id` (`hasil_id`),
  KEY `fk_sertifikat_user` (`user_id`),
  KEY `idx_sertifikat_verification` (`verification_code`),
  CONSTRAINT `fk_sertifikat_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `sertifikat_ibfk_2` FOREIGN KEY (`hasil_id`) REFERENCES `hasil_ujian` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE `sesi_ujian` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `nama_peserta` varchar(100) NOT NULL,
  `user_id` int(11) DEFAULT NULL,
  `waktu_mulai` datetime DEFAULT current_timestamp(),
  `waktu_selesai` datetime DEFAULT NULL,
  `durasi_menit` int(11) NOT NULL,
  `soal_teracak` text DEFAULT NULL,
  `jawaban_sementara` text DEFAULT NULL,
  `status` enum('berjalan','selesai','timeout') DEFAULT 'berjalan',
  `ability_estimate` decimal(10,4) DEFAULT 0.0000 COMMENT 'estimated ability level',
  `ability_history` text DEFAULT NULL COMMENT 'JSON array of ability estimates during exam',
  `confidence_level` decimal(5,4) DEFAULT 0.0000 COMMENT 'confidence in ability estimate',
  `cat_enabled` tinyint(1) DEFAULT 0 COMMENT 'whether CAT is enabled for this session',
  PRIMARY KEY (`id`),
  KEY `idx_sesi_user` (`user_id`),
  KEY `idx_sesi_status` (`status`),
  KEY `idx_sesi_ujian_user` (`user_id`),
  KEY `idx_sesi_ujian_status` (`status`),
  KEY `idx_sesi_ujian_waktu` (`waktu_mulai`),
  CONSTRAINT `fk_sesi_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=20 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Indexes added for session tracking and active session queries';


CREATE TABLE `soal` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `kategori_id` int(11) NOT NULL,
  `learning_topic_id` int(11) DEFAULT NULL,
  `materi_id` int(11) DEFAULT NULL,
  `sub_materi` varchar(255) DEFAULT NULL,
  `pertanyaan` text NOT NULL,
  `opsi_a` text NOT NULL,
  `opsi_b` text NOT NULL,
  `opsi_c` text NOT NULL,
  `opsi_d` text NOT NULL,
  `opsi_e` text NOT NULL,
  `jawaban_benar` char(1) NOT NULL,
  `pembahasan` text DEFAULT NULL,
  `tips` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `tingkat` enum('mudah','sedang','sulit') DEFAULT 'sedang',
  `irt_a` decimal(5,4) DEFAULT NULL COMMENT 'discrimination parameter',
  `irt_b` decimal(5,4) DEFAULT NULL COMMENT 'difficulty parameter',
  `irt_c` decimal(5,4) DEFAULT NULL COMMENT 'guessing parameter',
  `discrimination_index` decimal(5,4) DEFAULT NULL COMMENT 'point-biserial correlation',
  `item_quality` enum('excellent','good','fair','poor') DEFAULT NULL,
  `generated_by_ai` tinyint(1) DEFAULT 0 COMMENT 'whether question was generated by AI',
  `ai_model` varchar(100) DEFAULT NULL COMMENT 'AI model used for generation',
  `ai_generated_at` timestamp NULL DEFAULT NULL COMMENT 'when AI generated the question',
  `quality_score` decimal(5,4) DEFAULT NULL COMMENT 'AI quality score (0-1)',
  `review_status` enum('pending','approved','rejected') DEFAULT NULL COMMENT 'human review status',
  `reviewed_by` int(11) DEFAULT NULL COMMENT 'admin who reviewed the question',
  `reviewed_at` timestamp NULL DEFAULT NULL COMMENT 'when question was reviewed',
  `bloom_level` enum('remember','understand','apply','analyze','evaluate','create') DEFAULT NULL COMMENT 'Bloom taxonomy level',
  `cognitive_load` enum('low','medium','high') DEFAULT NULL COMMENT 'estimated cognitive load',
  `avg_time_seconds` int(11) DEFAULT NULL COMMENT 'average time to answer in seconds',
  `learning_objective` text DEFAULT NULL COMMENT 'learning objective this question tests',
  `expert_reviewed` tinyint(1) DEFAULT 0 COMMENT 'whether reviewed by subject matter expert',
  PRIMARY KEY (`id`),
  KEY `kategori_id` (`kategori_id`),
  KEY `idx_soal_irt_b` (`irt_b`),
  KEY `idx_soal_kategori` (`kategori_id`),
  KEY `idx_soal_tingkat` (`tingkat`),
  KEY `idx_soal_generated` (`generated_by_ai`),
  KEY `idx_soal_kategori_tingkat` (`kategori_id`,`tingkat`),
  KEY `idx_soal_kategori_tingkat_generated` (`kategori_id`,`tingkat`,`generated_by_ai`),
  CONSTRAINT `soal_ibfk_1` FOREIGN KEY (`kategori_id`) REFERENCES `kategori_soal` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=16547 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE `soal_frequency` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `soal_id` int(11) NOT NULL,
  `muncul_count` int(11) DEFAULT 0,
  `benar_count` int(11) DEFAULT 0,
  `salah_count` int(11) DEFAULT 0,
  `last_seen` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `irt_a` decimal(5,4) DEFAULT NULL,
  `irt_b` decimal(5,4) DEFAULT NULL,
  `irt_c` decimal(5,4) DEFAULT NULL,
  `discrimination_index` decimal(5,4) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `soal_id` (`soal_id`),
  KEY `idx_soal_freq_seen` (`soal_id`,`last_seen`),
  CONSTRAINT `soal_frequency_ibfk_1` FOREIGN KEY (`soal_id`) REFERENCES `soal` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=313 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE `soal_materi_mapping` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `soal_id` int(11) NOT NULL,
  `learning_topic_id` int(11) NOT NULL,
  `relevance_score` decimal(3,2) DEFAULT 1.00,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_mapping` (`soal_id`,`learning_topic_id`),
  KEY `learning_topic_id` (`learning_topic_id`),
  CONSTRAINT `soal_materi_mapping_ibfk_1` FOREIGN KEY (`soal_id`) REFERENCES `soal` (`id`),
  CONSTRAINT `soal_materi_mapping_ibfk_2` FOREIGN KEY (`learning_topic_id`) REFERENCES `learning_topics` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE `soal_topik` (
  `soal_id` int(11) NOT NULL,
  `topik_id` int(11) NOT NULL,
  PRIMARY KEY (`soal_id`,`topik_id`),
  KEY `topik_id` (`topik_id`),
  CONSTRAINT `soal_topik_ibfk_1` FOREIGN KEY (`soal_id`) REFERENCES `soal` (`id`) ON DELETE CASCADE,
  CONSTRAINT `soal_topik_ibfk_2` FOREIGN KEY (`topik_id`) REFERENCES `topik_pelajaran` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `supported_languages` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `language_code` varchar(10) NOT NULL,
  `language_name` varchar(100) NOT NULL,
  `native_name` varchar(100) NOT NULL,
  `is_active` tinyint(1) DEFAULT 1,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `language_code` (`language_code`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


CREATE TABLE `tips_soal` (
  `tips_id` int(11) NOT NULL,
  `soal_id` int(11) NOT NULL,
  PRIMARY KEY (`tips_id`,`soal_id`),
  KEY `soal_id` (`soal_id`),
  CONSTRAINT `tips_soal_ibfk_1` FOREIGN KEY (`tips_id`) REFERENCES `tips_tricks` (`id`) ON DELETE CASCADE,
  CONSTRAINT `tips_soal_ibfk_2` FOREIGN KEY (`soal_id`) REFERENCES `soal` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE `tips_tricks` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `kategori_id` int(11) DEFAULT NULL,
  `tipe_tips` enum('umum','spesifik','strategi','shortcut') DEFAULT 'umum',
  `judul` varchar(255) DEFAULT NULL,
  `konten` text DEFAULT NULL,
  `contoh` text DEFAULT NULL,
  `prioritas` int(11) DEFAULT 0,
  `aktif` tinyint(1) DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `kategori_id` (`kategori_id`),
  CONSTRAINT `tips_tricks_ibfk_1` FOREIGN KEY (`kategori_id`) REFERENCES `kategori_soal` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1631 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


